api.adaptor:
var data = payload.data || {};
function taskLocation(task, nodeMap){
  var node = nodeMap[task.taskId] || {};
  if(node.clusterCode) return node.clusterCode;
  if(task.executor === 'EDGE') return '边缘云';
  if(task.executor === 'CLOUD') return '中心云';
  if(task.executor === 'TERMINAL') return '端设备';
  return task.executor || '-';
}
function targetLabel(task, nodeMap){
  var node = nodeMap[task.taskId] || {};
  if(node.target === 'EDGE') return '边缘云';
  if(node.target === 'CLOUD') return '中心云';
  if(node.target === 'TERMINAL') return '端设备';
  return node.target || task.executor || '-';
}
var nodeMap = {};
(data.tasks || []).forEach(function(node){ nodeMap[node.id] = node; });
var levelRows = [];
(data.executionLevels || []).forEach(function(level){
  var tasks = level.tasks || [];
  tasks.forEach(function(task){
    levelRows.push({
      level: level.level,
      relation: tasks.length > 1 ? '本层并行' : '串行节点',
      taskId: task.taskId,
      taskName: task.taskName,
      taskType: task.taskType,
      location: taskLocation(task, nodeMap),
      inputPath: task.inputPath,
      outputPath: task.outputPath,
      expandedTasks: (task.expandedTasks || []).join(', ')
    });
  });
});
var nodeRows = (data.tasks || []).map(function(node){
  return {
    taskId: node.id,
    taskName: node.name,
    taskType: node.type,
    target: targetLabel({ taskId: node.id, executor: node.target }, nodeMap),
    clusterCode: node.clusterCode || (node.target === 'CLOUD' ? 'cloud-main' : '-'),
    image: node.image || '-',
    priority: node.priority,
    inputPath: node.inputPath,
    outputPath: node.outputPath
  };
});
var edgeRows = (data.edges || []).map(function(edge){
  var from = nodeMap[edge.from] || {};
  var to = nodeMap[edge.to] || {};
  return {
    from: edge.from,
    fromName: from.name || edge.from,
    to: edge.to,
    toName: to.name || edge.to,
    dataKey: edge.dataKey || '-',
    relation: (from.name || edge.from) + ' -> ' + (to.name || edge.to)
  };
});
data.levelRows = levelRows;
data.nodeRows = nodeRows;
data.edgeRows = edgeRows;
data.parallelSummary = levelRows.filter(function(row){ return row.relation === '本层并行'; }).length;
data.serialLevelCount = (data.executionLevels || []).length;
return { ...payload, status: payload.status === 200 ? 0 : payload.status, msg: payload.message, data: data };
